CREATE TABLE observation_events(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,request_id TEXT NOT NULL,job_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('request','auth','mcp','runtime','preview','ai','deployment','build','terminal','repair')),event TEXT NOT NULL,level TEXT NOT NULL CHECK(level IN ('info','warn','error')),status INTEGER,duration_ms INTEGER CHECK(duration_ms>=0),input_tokens INTEGER,output_tokens INTEGER,usage_reported INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX observation_project_cursor ON observation_events(project_id,id DESC);
CREATE INDEX observation_project_request ON observation_events(project_id,request_id,id DESC);
CREATE INDEX observation_project_job ON observation_events(project_id,job_id,id DESC);
CREATE TRIGGER observation_retention AFTER INSERT ON observation_events BEGIN DELETE FROM observation_events WHERE project_id IS NEW.project_id AND (created_at<NEW.created_at-604800000 OR id IN (SELECT id FROM observation_events WHERE project_id IS NEW.project_id ORDER BY id DESC LIMIT -1 OFFSET 1000)); END;
CREATE TABLE observation_timeline(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,job_id TEXT NOT NULL,kind TEXT NOT NULL,event TEXT NOT NULL,trust TEXT NOT NULL,request_id TEXT,duration_ms INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX observation_timeline_project ON observation_timeline(project_id,job_id,id);
CREATE TRIGGER observation_timeline_immutable BEFORE UPDATE ON observation_timeline BEGIN SELECT RAISE(ABORT,'immutable_job_event'); END;
CREATE TRIGGER observation_timeline_retention AFTER INSERT ON observation_timeline BEGIN DELETE FROM observation_timeline WHERE project_id=NEW.project_id AND (created_at<NEW.created_at-604800000 OR id IN (SELECT id FROM observation_timeline WHERE project_id=NEW.project_id ORDER BY id DESC LIMIT -1 OFFSET 2000)); END;
ALTER TABLE build_jobs ADD COLUMN observation_request_id TEXT;
CREATE TRIGGER observation_build_created AFTER INSERT ON build_jobs BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'build',NEW.status,'browser-unverified',NEW.observation_request_id,NULL,NEW.created_at); END;
CREATE TRIGGER observation_build_status AFTER UPDATE OF status ON build_jobs WHEN OLD.status<>NEW.status BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'build',NEW.status,'browser-unverified',NEW.observation_request_id,NEW.duration_ms,CAST(strftime('%s','now') AS INTEGER)*1000); END;
ALTER TABLE terminal_jobs ADD COLUMN observation_request_id TEXT;
CREATE TRIGGER observation_terminal_created AFTER INSERT ON terminal_jobs BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'terminal',NEW.status,'browser-unverified',NEW.observation_request_id,NULL,NEW.created_at); END;
CREATE TRIGGER observation_terminal_status AFTER UPDATE OF status ON terminal_jobs WHEN OLD.status<>NEW.status BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'terminal',NEW.status,'browser-unverified',NEW.observation_request_id,NEW.duration_ms,CAST(strftime('%s','now') AS INTEGER)*1000); END;
ALTER TABLE previews ADD COLUMN observation_request_id TEXT;
CREATE TRIGGER observation_preview_created AFTER INSERT ON previews BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'preview',NEW.status,'browser-unverified',NEW.observation_request_id,NULL,NEW.created_at); END;
CREATE TRIGGER observation_preview_status AFTER UPDATE OF status ON previews WHEN OLD.status<>NEW.status BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'preview',NEW.status,'browser-unverified',NEW.observation_request_id,NULL,CAST(strftime('%s','now') AS INTEGER)*1000); END;
ALTER TABLE repair_sessions ADD COLUMN observation_request_id TEXT;
CREATE TRIGGER observation_repair_created AFTER INSERT ON repair_sessions BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'repair',NEW.status,'server-state',NEW.observation_request_id,NULL,NEW.created_at); END;
CREATE TRIGGER observation_repair_status AFTER UPDATE OF status ON repair_sessions WHEN OLD.status<>NEW.status BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'repair',NEW.status,'server-state',NEW.observation_request_id,NULL,CAST(strftime('%s','now') AS INTEGER)*1000); END;
ALTER TABLE ship_jobs ADD COLUMN observation_request_id TEXT;
CREATE TRIGGER observation_deployment_created AFTER INSERT ON ship_jobs BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'deployment',NEW.status,'server-state',NEW.observation_request_id,NULL,NEW.created_at); END;
CREATE TRIGGER observation_deployment_status AFTER UPDATE OF status ON ship_jobs WHEN OLD.status<>NEW.status BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.id,'deployment',NEW.status,'server-state',NEW.observation_request_id,NEW.finished_at-NEW.created_at,CAST(strftime('%s','now') AS INTEGER)*1000); END;
CREATE TRIGGER observation_build_receipt AFTER INSERT ON build_events BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,created_at) SELECT project_id,id,'build','output_received','browser-unverified',observation_request_id,NEW.created_at FROM build_jobs WHERE id=NEW.job_id; END;
CREATE TRIGGER observation_terminal_receipt AFTER INSERT ON terminal_events BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,created_at) SELECT project_id,id,'terminal','output_received','browser-unverified',observation_request_id,NEW.created_at FROM terminal_jobs WHERE id=NEW.job_id; END;
CREATE TRIGGER observation_preview_receipt AFTER INSERT ON preview_events BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,created_at) SELECT project_id,id,'preview',NEW.status,'browser-unverified',observation_request_id,NEW.created_at FROM previews WHERE id=NEW.preview_id; END;
CREATE TRIGGER observation_repair_receipt AFTER INSERT ON repair_events BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,created_at) SELECT project_id,id,'repair','diagnostic_received','server-state',observation_request_id,NEW.created_at FROM repair_sessions WHERE id=NEW.session_id; END;
ALTER TABLE ai_events ADD COLUMN duration_ms INTEGER;
ALTER TABLE ai_events ADD COLUMN usage_reported INTEGER;
CREATE TRIGGER observation_ai_event AFTER INSERT ON ai_events BEGIN INSERT INTO observation_timeline(project_id,job_id,kind,event,trust,request_id,duration_ms,created_at) VALUES(NEW.project_id,NEW.request_id,'ai',NEW.phase,'provider-event',NEW.request_id,NEW.duration_ms,NEW.created_at); END;
CREATE TRIGGER observation_job_log AFTER INSERT ON observation_timeline WHEN NEW.kind<>'ai' BEGIN INSERT INTO observation_events(project_id,request_id,job_id,kind,event,level,duration_ms,created_at) VALUES(NEW.project_id,COALESCE(NEW.request_id,NEW.job_id),NEW.job_id,NEW.kind,NEW.event,CASE WHEN NEW.event IN ('failed','runtime_error','timed_out','human_required') THEN 'error' WHEN NEW.event='blocked' THEN 'warn' ELSE 'info' END,NEW.duration_ms,NEW.created_at); END;
